import java.util.*;
import java.io.*;
import java.math.*;

public class BasicJava
{
   public static void main(String[] args)
   {
      Task Main = new Task();

      Main.solve();
   }

   public static class Task
   {
      public InputReader in = new InputReader(System.in);
      public PrintWriter out = new PrintWriter(System.out);

      public void solve()
      {
         int w = in.nextInt();
         int m = in.nextInt();

         int[] t = new int[110];

         int nr = 0;

         while (m > 0) {

            nr++; t[nr] = m % w;

            m = m / w;

         }

         for (int i = 1; i <= nr; i++)
            if (t[i] > w / 2) {

               t[i] = - (t[i] - w);

               t[i + 1] ++;


            }

         if (t[nr] == 1) nr++;

         for (int i = 1; i <= nr; i++)
            if (t[i] > 1) {

               System.out.println("NO");

               System.exit(0);

            }

         System.out.println("YES");

      }
   }

   static class InputReader
   {
      private InputStream stream;
      private byte[] buf = new byte[2048];
      private int curChar;
      private int numChars;

      public InputReader(InputStream stream)
      {
         this.stream = stream;
      }

      public int read()
      {
         if (numChars == -1)
            throw new UnknownError();
         if (curChar >= numChars)
         {
            curChar = 0;
            try
            {
               numChars = stream.read(buf);
            }
            catch (IOException e)
            {
               throw new UnknownError();
            }
            if (numChars <= 0)
               return -1;
         }
         return buf[curChar++];
      }

      public int peek()
      {
         if (numChars == -1)
            return -1;
         if (curChar >= numChars)
         {
            curChar = 0;
            try
            {
               numChars = stream.read(buf);
            }
            catch (IOException e)
            {
               return -1;
            }
            if (numChars <= 0)
               return -1;
         }
         return buf[curChar];
      }

      public void skip(int x)
      {
         while (x-- > 0)
            read();
      }

      public int nextInt()
      {
         return Integer.parseInt(next());
      }

      public long nextLong()
      {
         return Long.parseLong(next());
      }

      public String nextString()
      {
         return next();
      }

      public String next()
      {
         int c = read();
         while (isSpaceChar(c))
            c = read();
         StringBuffer res = new StringBuffer();
         do
         {
            res.appendCodePoint(c);
            c = read();
         }
         while (!isSpaceChar(c));

         return res.toString();
      }

      public String nextLine()
      {
         StringBuffer buf = new StringBuffer();
         int c = read();
         while (c != '\n' && c != -1)
         {
            if (c != '\r')
               buf.appendCodePoint(c);
            c = read();
         }
         return buf.toString();
      }

      public double nextDouble()
      {
         int c = read();
         while (isSpaceChar(c))
            c = read();
         int sgn = 1;
         if (c == '-')
         {
            sgn = -1;
            c = read();
         }
         double res = 0;
         while (!isSpaceChar(c) && c != '.')
         {
            if (c == 'e' || c == 'E')
               return res * Math.pow(10, nextInt());
            if (c < '0' || c > '9')
               throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
         }
         if (c == '.')
         {
            c = read();
            double m = 1;
            while (!isSpaceChar(c))
            {
               if (c == 'e' || c == 'E')
                  return res * Math.pow(10, nextInt());
               if (c < '0' || c > '9')
                  throw new InputMismatchException();
               m /= 10;
               res += (c - '0') * m;
               c = read();
            }
         }
         return res * sgn;
      }

      public boolean hasNext()
      {
         int value;
         while (isSpaceChar(value = peek()) && value != -1)
            read();
         return value != -1;
      }

      private boolean isSpaceChar(int c)
      {
         return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
      }

   }

}
